import assert from 'node:assert/strict';
export async function runMotionScatterDragSmoke(page){
 const previous=await page.evaluate(()=>({project:JSON.stringify(project),curPage,curSec,curEl,curPane,selection,secFocus,mode:NAGWEB_STORY_EDITOR.canvasMode(),timeline:NAGWEB_STORY_TIMELINE_UI.state()}));
 const frame='.nw-motion-dialog iframe',edit='[data-motion-scatter-edit]';let revision=0;
 async function ready(){await page.waitForFunction(()=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.querySelectorAll('[data-nw-stream-slot]').length===8&&d.querySelector('.nw-scatter-dial-surface')&&Array.from(d.querySelectorAll('[data-nw-stream-slot]'),n=>!!n.__nwMotionInstances&&n.querySelector('img')?.complete&&n.querySelector('img').naturalWidth).every(Boolean);},{timeout:15000});}
 async function change(selector,value){const mark='drag-'+(++revision);await page.$eval(selector,(n,{value,mark})=>{document.querySelector('.nw-motion-dialog iframe').contentDocument.body.dataset.dragOld=mark;n.value=value;n.dispatchEvent(new Event('change',{bubbles:true}));},{value,mark});await page.waitForFunction(mark=>{const d=document.querySelector('.nw-motion-dialog iframe')?.contentDocument;return d?.body&&d.body.dataset.dragOld!==mark;},{},mark);await ready();}
 async function fields(){return page.$$eval('[data-motion-scatter-point]',ns=>Object.fromEntries(ns.map(n=>[n.dataset.motionScatterPoint,+n.value])));}
 async function pose(p,selector=frame,gid){return page.$eval(selector,(f,{p,gid})=>{const d=f.contentDocument;f.contentWindow.__NAG_SCROLL_DIRECTOR[gid||d.querySelector('.sc').dataset.id].set(p);return Array.from(d.querySelectorAll('[data-nw-stream-slot]'),n=>({id:n.dataset.id,tiles:n.__nwMotionInstances,clip:n.__nwMotionClip}));},{p,gid});}
 async function screen(){return page.$eval(frame,f=>{const d=f.contentDocument,n=d.querySelector('[data-nw-stream-slot]'),host=n.offsetParent,t=n.__nwMotionInstances[0],clip=n.__nwMotionClip,fr=f.getBoundingClientRect(),r=host.getBoundingClientRect(),pad=Math.min(clip.width,clip.height)*+(document.querySelector('[data-motion-stream="padding"]').value)/100;return{x:fr.left+f.clientLeft+r.left+t.center.x*r.width/host.clientWidth,y:fr.top+f.clientTop+r.top+t.center.y*r.height/host.clientHeight,width:(clip.width-2*pad)*r.width/host.clientWidth,height:(clip.height-2*pad)*r.height/host.clientHeight};});}
 async function drag(dx,dy,cancel){const p=await screen();await page.mouse.move(p.x,p.y);await page.mouse.down();await page.mouse.move(p.x+p.width*dx/100,p.y+p.height*dy/100,{steps:4});if(cancel)await page.keyboard.press('Escape');await page.mouse.up();return fields();}
 function near(actual,expected,label){assert.ok(Math.abs(actual-expected)<.015,`${label}: ${actual} vs ${expected}`);}
 function checkPoint(cards,point,padding){const {clip,tiles}=cards[0],pad=Math.min(clip.width,clip.height)*padding/100;near(tiles[0].center.x,clip.left+pad+(clip.width-2*pad)*point.x/100,'export X');near(tiles[0].center.y,clip.top+pad+(clip.height-2*pad)*point.y/100,'export Y');}
 try{
  await page.evaluate(()=>{project.pages[0].sections=[mkSection({layout:'free',sdEnabled:false,elements:[mkEl('label',{text:'Exterior al grupo'})]})];curPage=0;curSec=0;curEl=0;selection=[];secFocus=false;saveProject();renderPane();renderPreview();history=[];future=[];NAGWEB_MOTION_LAB.open();});await page.click('[data-motion-template="scatter-dial"]');await ready();await page.click('[data-motion-library-tab="elements"]');const id=await page.$eval(frame,f=>f.contentDocument.querySelector('[data-nw-stream-slot]').dataset.id);await page.click('[data-motion-layer="'+id+'"]');await page.select('[data-motion-scatter-step]','0');await page.click('[data-motion-scatter-view]');const initial=await fields(),original=await pose(0),ring=await pose(.51);await page.click('[data-motion-scatter-view]');
  // Ordinary selection never edits procedural geometry, even at an editable phase.
  assert.deepEqual(await drag(5,3),initial);await page.click(edit);assert.equal(await page.$eval(edit,n=>n.getAttribute('aria-pressed')),'true');
  assert.deepEqual(await drag(4,3,true),initial,'Canceling the first edit keeps the default trajectory');assert.equal(await page.$eval('[data-motion-scatter-reset]',n=>n.disabled),true);
  await page.$eval(frame,f=>{f.contentDocument.body.dataset.dragDocument='stable';f.contentWindow.__dragCanvas=f.contentDocument.querySelector('.nw-scatter-dial-surface');f.contentWindow.__dragNode=f.contentDocument.querySelector('[data-nw-stream-slot]');});
  const moved=await drag(7,5);near(moved.x,initial.x+7,'drag X');near(moved.y,initial.y+5,'drag Y');assert.equal(moved.size,initial.size);assert.equal(await page.$eval(frame,f=>f.contentDocument.body.dataset.dragDocument),'stable');assert.equal(await page.$eval(frame,f=>f.contentWindow.__dragCanvas===f.contentDocument.querySelector('.nw-scatter-dial-surface')&&f.contentWindow.__dragNode===f.contentDocument.querySelector('[data-nw-stream-slot]')),true);
  const opening=await pose(0);for(let i=1;i<8;i++)assert.deepEqual(opening[i],original[i]);checkPoint(opening,moved,6);assert.deepEqual(await pose(.51),ring);checkPoint(await pose(1),moved,6);await page.click('[data-motion-scatter-view]');await page.click(edit);
  assert.deepEqual(await drag(9,6,true),moved,'Escape restores the entire path without recreating the iframe');assert.equal(await page.$eval(edit,n=>n.getAttribute('aria-pressed')),'true');
  // Capture loss also restores a pending move.
  const pos=await screen();await page.mouse.move(pos.x,pos.y);await page.mouse.down();await page.mouse.move(pos.x+20,pos.y+10);await page.$eval(frame,f=>{const n=f.contentWindow.__dragNode;n.dispatchEvent(new PointerEvent('pointercancel',{bubbles:true,pointerId:1}));});await page.mouse.up();assert.deepEqual(await fields(),moved);
  await page.select('[data-motion-scatter-step]','1');assert.equal(await page.$eval(edit,n=>n.getAttribute('aria-pressed')),'false');const step1=await fields();await page.click(edit);const second=await drag(3,-4);near(second.x,step1.x+3,'second stage X');near(second.y,step1.y-4,'second stage Y');await page.select('[data-motion-scatter-step]','0');assert.deepEqual(await fields(),moved);await page.select('[data-motion-scatter-step]','2');await page.click('[data-motion-scatter-view]');const thirdBefore=await fields();
  // Fitted frame padding and a CSS-scaled parent both affect pointer deltas.
  await change('[data-motion-stream="padding"]','12');await page.$eval(frame,f=>{const n=f.contentDocument.querySelector('[data-nw-stream-slot]').offsetParent;n.style.transform='scale(.8)';n.style.transformOrigin='0 0';});await page.click(edit);const third=await drag(-4,3);near(third.x,thirdBefore.x-4,'scaled padded X');near(third.y,thirdBefore.y+3,'scaled padded Y');checkPoint(await pose(60/532),third,12);
  await page.$eval('[data-motion-progress]',n=>{n.value='51';n.dispatchEvent(new Event('input',{bubbles:true}));});assert.equal(await page.$eval(edit,n=>n.getAttribute('aria-pressed')),'false');await page.click(edit);await page.click('[data-motion-play]');assert.equal(await page.$eval(edit,n=>n.getAttribute('aria-pressed')),'false');await page.click('[data-motion-play]');
  await page.emulateMediaFeatures([{name:'prefers-reduced-motion',value:'reduce'}]);await page.waitForFunction(()=>document.querySelector('[data-motion-scatter-edit]').disabled);assert.equal(await page.$eval(edit,n=>n.disabled),true);await page.emulateMediaFeatures([]);await page.waitForFunction(()=>!document.querySelector('[data-motion-scatter-edit]').disabled);assert.equal(await page.$eval(edit,n=>n.disabled),false);
  await page.select('[data-motion-scatter-step]','0');await change('[data-motion-config="source"]','scroll');await change('[data-motion-stream="start"]','20');await change('[data-motion-stream="end"]','80');await change('[data-motion-stream="turns"]','3');await page.click(edit);const scroll=await drag(2,1);near(scroll.x,moved.x+2,'scroll X');near(scroll.y,moved.y+1,'scroll Y');checkPoint(await pose(.2),scroll,12);assert.ok(Math.abs(await page.$eval(frame,f=>{const d=f.contentDocument;return f.contentWindow.__NAG_SCROLL_DIRECTOR[d.querySelector('.sc').dataset.id].progress();})-.2)<1e-7);
  await page.click('[data-motion-insert-group]');const gid=await page.evaluate(()=>sec().elements.find(e=>e.nwMotionInstance).id),saved=await page.evaluate(id=>sec().elements.find(e=>e.id===id)?.nwScatterPath,id);assert.equal(saved.length,3);near(saved[0].x,scroll.x,'saved X');near(saved[1].x,second.x,'saved second stage');near(saved[2].y,third.y,'saved third stage');assert.equal(await page.evaluate(()=>sec().elements[0].text),'Exterior al grupo');
  await page.evaluate(()=>{const f=document.createElement('iframe');f.id='scatter-drag-export';f.style.cssText='width:900px;height:620px';f.srcdoc=generateSite(flattenPage(page()),false,false,false);document.body.append(f);});await page.waitForFunction(gid=>{const f=document.querySelector('#scatter-drag-export'),d=f?.contentDocument;return f?.contentWindow.__NAG_SCROLL_DIRECTOR?.[gid]&&d.querySelector('[data-nw-stream-slot]')?.__nwMotionInstances;},{timeout:15000},gid);checkPoint(await pose(.2,'#scatter-drag-export',gid),scroll,12);checkPoint(await pose((20+(60/532)/3*60)/100,'#scatter-drag-export',gid),third,12);
  await page.evaluate(gid=>NAGWEB_MOTION_LAB.edit(gid),gid);await ready();await page.click('[data-motion-library-tab="elements"]');await page.click('[data-motion-layer="'+id+'"]');await page.select('[data-motion-scatter-step]','0');assert.deepEqual(await fields(),scroll);assert.equal(await page.$eval(edit,n=>n.getAttribute('aria-pressed')),'false');
  console.log('Scatter canvas drag: native picking/deltas, live canvas identity, per-stage/image isolation, coherent return/ring, Escape/pointercancel, padded/scaled preview, play/scrub/reduced-motion guards, scroll and persisted/reopened/exported paths OK');
 }catch(error){console.error(error);await page.screenshot({path:'/tmp/scatter-drag-failure.png'}).catch(()=>{});throw error;}finally{await page.mouse.up().catch(()=>{});await page.emulateMediaFeatures([]);await page.evaluate(p=>{document.querySelector('.nw-motion-dialog').close();document.querySelector('#scatter-drag-export')?.remove();clearTimeout(previewTimer);project=JSON.parse(p.project);curPage=p.curPage;curSec=p.curSec;curEl=p.curEl;curPane=p.curPane;selection=p.selection;secFocus=p.secFocus;history=[];future=[];NAGWEB_STORY_EDITOR.setCanvasMode(p.mode);NAGWEB_STORY_TIMELINE_UI.setState(p.timeline);saveProject();renderScenes();renderPane();renderPreview();},previous);}
}
